package auth

import (
	"strings"
	"testing"
)

// Generated by node-argon2 0.45.1 with its default costs and the fixed test salt
// WebMuxIssue257QA!. Keep this independent of the Go password encoder.
const nodePasswordHash = "$argon2id$v=19$m=65536,p=4,t=3$V2ViTXV4SXNzdWUyNTdRQSE$BIkSauu31TA8mx1843EMfcy6XfEUkN6607GqA2UQfFM"

func TestNodePasswordParameterOrdering(t *testing.T) {
	for _, params := range []string{
		"m=65536,t=3,p=4", "m=65536,p=4,t=3", "t=3,m=65536,p=4",
		"t=3,p=4,m=65536", "p=4,m=65536,t=3", "p=4,t=3,m=65536",
	} {
		t.Run(params, func(t *testing.T) {
			hash := strings.Replace(nodePasswordHash, "m=65536,p=4,t=3", params, 1)
			if ok, err := VerifyPassword(hash, "webmux-compatibility-🔐"); err != nil || !ok {
				t.Fatalf("node-argon2 password rejected: %v", err)
			}
			if ok, err := VerifyPassword(hash, "wrong"); err != nil || ok {
				t.Fatalf("incorrect password: accepted=%v error=%v", ok, err)
			}
		})
	}
}

func TestPasswordParametersRejectAmbiguityAndExcessiveCosts(t *testing.T) {
	for _, params := range []string{
		"m=65536,p=4", "m=65536,p=4,t=3,x=1", "m=65536,m=65536,t=3",
		"p=4,t=3,x=65536", "p=4,t=3,m=", "p=4,t=3,m=+65536",
		"p=4,t=3,m=-65536", "p=4,t=3,m= 65536", "p=4,t=3,m=65536 ",
		"p=4,t=3,M=65536", "p=4,t=3,m=65536=1", "p=0,t=3,m=65536",
		"p=17,t=3,m=65536", "p=256,t=3,m=65536", "p=4,t=0,m=65536",
		"p=4,t=11,m=65536", "p=4,t=3,m=31", "p=4,t=3,m=262145",
		"p=4,t=3,m=4294967296", "p=4,t=3,m=" + strings.Repeat("9", 1024),
	} {
		t.Run(params, func(t *testing.T) {
			hash := strings.Replace(nodePasswordHash, "m=65536,p=4,t=3", params, 1)
			if ok, err := VerifyPassword(hash, "webmux-compatibility-🔐"); err == nil || ok {
				t.Fatalf("invalid hash accepted: %v", err)
			}
		})
	}
}
